def can_make_abc(cards):
    # Check if the cards can be rearranged to form 'abc'
    if 'abc' in cards:
        return 'YES'

    # Try to find a pair of cards that can be swapped to form 'abc'
    for i in range(len(cards)):
        for j in range(i+1, len(cards)):
            if cards[i] + cards[j] == 'abc':
                return 'YES'

    return 'NO'

