def max_absolute_difference(n, a):
    max_diff = 0
    for k in range(1, n + 1):
        total_weight = sum(a)
        if total_weight % k == 0:
            trucks = [total_weight // k] * n
            for i in range(n):
                if trucks[i] % k != 0:
                    break
            else:
                max_diff = max(max_diff, trucks[0] - trucks[1])
    return max_diff

