def max_string_length(x, y, z):
    # Create a 3D array to store the maximum length of the string
    dp = [[[0 for _ in range(z + 1)] for _ in range(y + 1)] for _ in range(x + 1)]

    # Initialize the base case
    for i in range(x + 1):
        dp[i][0][0] = i

    # Fill the dp table
    for i in range(1, x + 1):
        for j in range(1, y + 1):
            for k in range(1, z + 1):
                if x == 1 and y == 1 and z == 1:
                    dp[i][j][k] = i + j + k
                elif x == 1 and y == 1:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k])
                elif x == 1:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k - 1])
                elif y == 1:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k - 1])
                else:
                    dp[i][j][k] = max(dp[i - 1][j][k], dp[i][j - 1][k])

    return dp[x][y][z]

