    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for l in range(i):
                if s[l:i] == s[l:i][::-1]:
                    dp[i][j] = min(dp[i][j], dp[l][j - 1] + 1)

    return dp[n][k]

def count_ways(n, x):
