def permuteVowels(s: str) -> str:
    vowels = 'aeiou'
    s = list(s)
    vowels_list = sorted(vowels)

    def permute(s, i, result):
        if i == len(s):
            return ''.join(result)

        for j in range(i, len(s)):
            if s[i] in vowels_list and s[j] in vowels_list:
                result.append(s[i])
                result.append(s[j])
            else:
                result.append(s[i])
                result.append(s[j])
        return permute(s, i + 1, result)

    return permute(s, 0, [])

def find_dominant_split(nums):
    freq = {}
    dominant_element = None

    for num in nums:
        freq[num] = freq.get(num, 0) + 1
        if freq[num] * 2 > len(nums):
            dominant_element = num
            break

    if dominant_element is None:
        return -1

    min_index = len(nums) - 1

    for i in range(len(nums) - 1):
        if nums[i] == dominant_element:
            if freq[nums[i]] * 2 > len(nums) - i:
                min_index = i
                break

    return min_index

def maxBeauty(nums, k):
    nums.sort()
    left = 0
    right = len(nums) - 1
    max_beauty = 0

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] - nums[mid - 1] <= k:
            max_beauty = mid + 1
            left = mid + 1
        else:
            right = mid - 1

    return max_beauty

