    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(m + 1):
            if j == 0:
                dp[i][j] = True
            elif j == 1:
                dp[i][j] = True
            else:
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]

    return dp[n][m]

