class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [1]*n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
            elif self.rank[root_u] < self.rank[root_v]:
                self.parent[root_u] = root_v
            else:
                self.parent[root_v] = root_u
                self.rank[root_u] += 1

def is_good_graph(n, edges, K, x, y):
    uf = UnionFind(n)
    for u, v in edges:
        uf.union(u, v)

    for i in range(K):
        if uf.find(x) == uf.find(y):
            return "No"
    return "Yes"

