def shift_outer_squares(grid):
    N = len(grid)
    shifted_grid = [[0]*N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            if i == 0 or j == 0:
                shifted_grid[i][j] = grid[i][j]
            elif i == N-1 or j == N-1:
                shifted_grid[i][j] = grid[i][j]
            else:
                shifted_grid[i][j] = 1 - shifted_grid[i+1][j] + shifted_grid[i-1][j] - shifted_grid[i][j+1] + shifted_grid[i][j-1]

    return shifted_grid

