    min_seconds = float('inf')

    # Iterate over each reel
    for i in range(M):
        # Calculate the time to stop the i-th reel
        seconds_to_stop = (i + 1) % M

        # Check if all reels can be stopped in this time
        if all(S[i] == S[j] for i, j in zip(range(M), range(M))):
