def find_matching_strings(N, T_prime, S):
    # Convert T_prime to a list for easier manipulation
    T_prime_list = list(T_prime)

    # Check if T_prime is equal to T
    if T_prime_list == T:
        return N, T_prime_list

    # Check if T_prime is obtained by inserting one character at one position
    for i in range(N):
        for j in range(N):
            if T_prime_list[i] == T_prime_list[j] + S[i]:
                return N, T_prime_list

    # Check if T_prime is obtained by deleting one character from T
    for i in range(N):
        if T_prime_list.pop(i) == T_prime_list:
            return N, T_prime_list

    # Check if T_prime is obtained by changing one character in T
    for i in range(N):
        if T_prime_list[i] != T_prime_list[i+1]:
            return N, T_prime_list

    return -1, []

