def solve(N):
    grid = [[0]*N for _ in range(N)]
    grid[N//2][N//2] = 1

    def backtrack(i, j):
        if i == N-1 and j == N-1:
            return True
        if i == N-1:
            return backtrack(j, N-1)
        if j == N-1:
            return backtrack(i, j-1)

        for x in range(1, N**2):
            if grid[i][j] == 0:
                grid[i][j] = x
                if backtrack(i+1, j) or backtrack(i, j+1):
                    return True
                grid[i][j] = 0
        return False

    if backtrack(0, 0):
        for i in range(N):
            for j in range(N):
                print(grid[i][j], end=' ')
            print()
    else:
        print("No solution")

