def min_moves(N, S):
    # Initialize the player positions
    player1 = None
    player2 = None

    # Find the positions of the two players
    for i in range(N):
        for j in range(N):
            if S[i][j] == 'P':
                if player1 is None:
                    player1 = (i, j)
                else:
                    if player2 is None:
                        player2 = (i, j)
                    else:
                        if player1[1] == player2[1]:
                            return -1
                        player1 = (i, j)
                        player2 = (i, j)

    # If there is only one player, return 0
    if player1 is None:
        return 0

    # If there are two players, return -1
    if player2 is None:
        return -1

    # Calculate the minimum moves required to bring the two players to the same cell
    moves = 0
    while player1 != player2:
        # Choose the direction with the least number of moves
        if player1[0] > player2[0]:
            moves += 1
            player1 = (player1[0] - 1, player1[1])
        elif player1[0] < player2[0]:
            moves += 1
            player1 = (player1[0] + 1, player1[1])
        else:
            moves += 1
            player1 = (player1[0], player1[1] - 1)
            player2 = (player2[0], player2[1] - 1)

    return moves

