    n = R - L + 1
    dp = [[float('inf')] * n for _ in range(n)]
    dp[L][L] = 1

    for i in range(L, n):
        for j in range(i, n):
            dp[i][j] = dp[i][j-1] + dp[i+1][j]
            if dp[i][j] < dp[i][j-1] + dp[i+1][j]:
                dp[i][j] = dp[i][j-1] + dp[i+1][j]

    min_m = min(dp[L][i] for i in range(L, n))
    l, r = L, R
    while l < r:
        mid = (l + r) // 2
        if dp[l][mid] + dp[mid+1][r] < dp[l][r]:
            r = mid
        else:
            l = mid + 1

