def can_win(N, cards):
    from functools import lru_cache

    @lru_cache(None)
    def game(mask):
        if mask == (1 << N) - 1:
            return True
        for i in range(N):
            if not (mask & (1 << i)):
                new_mask = mask | (1 << i)
                if not game(new_mask):
                    return True
        return False

    return "Takahashi" if game(0) else "Aoki"

