        return res

    return getCoins(coins, k)

def minimumSum(nums, andValues):
    n = len(nums)
    m = len(andValues)

    # Initialize the minimum sum to a large number
    min_sum = float('inf')

    # Iterate over all possible ways to split nums into m subarrays
    for i in range(n - m + 1):
        current_sum = 0
        for j in range(i, n - m + 1):
            current_sum += nums[j]
            if current_sum == andValues[j]:
                min_sum = min(min_sum, current_sum)
                break

    # If min_sum is still infinity, it means it's not possible to split nums into m subarrays
    if min_sum == float('inf'):
        return -1
    else:
        return min_sum

def encrypt(nums):
    def max_digit(num):
        return max(str(num))

    return sum(int(str(num)[i]) for i in range(len(num)))

def mark_and_sum(nums, queries):
    n = len(nums)
    answer = []

    for index_i, k_i in queries:
        marked = False
        marked_elements = []

        for i in range(n):
            if not marked:
                if i == index_i:
                    marked = True
                else:
                    if nums[i] != nums[index_i]:
                        marked_elements.append(nums[i])
                        marked = True

        if not marked:
            answer.append(sum(marked_elements))

    return answer

def minValue(s: str) -> str:
    n = len(s)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        if s[i - 1] == '?':
            dp[i] = min(dp[i - 1], dp[i - 2] + 1)
        else:
            dp[i] = min(dp[i - 1], dp[i - 2])

    return ''.join(s[i] for i in range(n) if s[i] != '?' and dp[i] == dp[i - 1])

def sumOfPower(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    power = 0

    # Generate all possible subsequences
    for i in range(1, 1 << n):
        subseq = []
        for j in range(n):
            if i & (1 << j):
                subseq.append(nums[j])

        if sum(subseq) == k:
            power += 1

    return power % MOD

def minLevelsToWin(possible):
    n = len(possible)
    dp = [[-1 for _ in range(n+1)] for _ in range(n+1)]

    for i in range(n):
        dp[i][0] = i
        dp[0][i] = -1

    for i in range(1, n+1):
        for j in range(i):
            if possible[j] == 1 and dp[j][i-1] != -1:
                dp[i][i] = max(dp[i][i], dp[j][i-1] + 1)
            if possible[j] == 0 and dp[j][i-1] != -1:
                dp[i][i] = max(dp[i][i], dp[j][i-1] - 1)

    return dp[n][n]

def count_subarrays(nums):
    count = 0
    max_num = max(nums)
    for i in range(len(nums)):
        if nums[i] == max_num:
            count += 1
    return count

def minimum_possible_value(n, x):
    nums = [0] * n
    for i in range(n - 1):
        nums[i + 1] = nums[i] + (x & nums[i])
    return nums[n - 1]

def median_of_uniqueness(nums):
    n = len(nums)
    uniqueness = []
    for i in range(n):
        distinct = set()
        for j in range(i, n):
            distinct.add(nums[j])
            uniqueness.append(len(distinct))
    uniqueness.sort()
    if n % 2 == 0:
        return uniqueness[n//2]
    else:
        return uniqueness[n//2 - 1]

def isValidWord(word):
    vowels = "aeiouAEIOU"
    if len(word) < 3 or not word.isalnum():
        return False
    for char in word:
        if not char.isalnum():
            return False
    for char in word:
        if char not in vowels:
            return False
    return True

def minOperations(word: str, k: int) -> int:
    n = len(word)
    if n % k != 0:
        return -1

    operations = 0
    i = 0
    while i < n:
        j = i + k - 1
        while j < n:
            if word[i:i+k] == word[j:j+k]:
                i += 1
                j += 1
            else:
                break
        operations += 1
        i += 1
    return operations

def minLength(s: str) -> int:
    count = {}
    for char in s:
        count[char] = count.get(char, 0) + 1
    min_len = len(s)
    for char in count:
        min_len = min(min_len, len(s) - count[char])
    return min_len

def minCost(nums, cost1, cost2):
    MOD = 10**9 + 7
    nums.sort()
    n = len(nums)
    total_cost = 0

    for i in range(n):
        if i == 0:
            total_cost += nums[i] * cost1
        elif i == n - 1:
            total_cost += nums[i] * cost2
        else:
            total_cost += nums[i] * cost1 + nums[i + 1] * cost2

    return total_cost % MOD

def validate_2x2_square(grid):
    for i in range(2):
        for j in range(2):
            if grid[i][j] == grid[i][j+1] == grid[i+1][j] == grid[i+1][j+1]:
                return True
    return False

def count_right_triangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                count += 1
                if i > 0 and grid[i-1][j] == 1:
                    count += 1
                if j > 0 and grid[i][j-1] == 1:
                    count += 1
    return count

def numStableBinaryArrays(zero, one, limit):
    MOD = 10**9 + 7
    dp = [[0] * (one + 1) for _ in range(zero + 1)]
    dp[0][0] = 1

    for i in range(1, zero + 1):
        for j in range(1, one + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if j < one:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

    return dp[zero][one]

def permutation_difference(s, t):
    s_index = {c: i for i, c in enumerate(s)}
    t_index = {c: i for i, c in enumerate(t)}
    return sum(abs(s_index[c] - t_index[c]) for c in s)

def digitDifference(nums):
    total_sum = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            total_sum += sum(set(str(nums[i]) + str(nums[j])))
    return total_sum

def count_good_pairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % (nums2[j] * k) == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    while word:
        c = word[0]
        count = 0
        while word and word[0] == c:
            count += 1
            word = word[1:]
        comp += str(count) + c
    return comp

def maxSubsequenceSum(nums, queries):
    MOD = 10**9 + 7

    def maxSubseq(nums, pos, x):
        if pos == 0:
            return x

        max_sum = 0
        for i in range(pos, len(nums)):
            if i - pos >= 0 and nums[i] != nums[i - 1]:
                max_sum = max(max_sum, maxSubseq(nums, i - 1, x - nums[i - 1]))

        return max_sum % MOD

    ans = 0
    for pos, x in queries:
        ans = (ans + maxSubseq(nums, pos, x)) % MOD

    return ans

def min_partitions(s):
    count = {}
    for char in s:
        count[char] = count.get(char, 0) + 1

    min_partitions = 0
    for char in count:
        if count[char] % 2 != 0:
            min_partitions += 1
            count[char] = 0

    return min_partitions

def find_index(nums, queries, x):
    answer = [-1] * len(queries)
    for i, query in enumerate(queries):
        count = nums.count(x)
        if count >= query:
            answer[i] = count
        else:
            answer[i] = -1
    return answer
